using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Linq;
namespace BeamScheduleFormatter {
/* Printed bar bending schedule and cutting list (owner, 19 November 2026: "Standard presentation ng bbs at cutting list", "dapat
   lahat ng report ganito"): schedule information, shape key, the schedule with a sketch of every bar, weights, the cutting
   pattern of each commercial bar, the NSCP 2015 special moment frame detailing check, review items and blank signatures. */
class BbsInfo {public string Number="",Revision="",Status="",Source="",Curtailment="",Prepared="",Checked="",Approved="";}
static partial class BbsReport {
 static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 /* shape codes of this schedule; the sketch and A / B / C define the bend */
 internal static string Code(string shape){switch(shape){case "CRANK":return "K4";case "CRANKHOOK":return "K5";case "HOOK1":return "L1";case "HOOK2":return "U2";case "HOOP":return "H5";case "CROSSTIE":return "X3";default:return "S0";}}
 /* BBS sketches are schematic: long straight parts are shortened so that the hooks read */
 static CutPiece Schematic(CutPiece p){switch(p.ShapeCode){case "CRANK":{var q=Sample("CRANK",p.DimA,p.DimB,p.DimC);q.DimD=Math.Min(p.DimD,3*Math.Max(p.DimA,1));q.Diameter=p.Diameter;return q;}case "CRANKHOOK":{var q=Sample("CRANKHOOK",p.DimA,p.DimB,p.DimC);q.DimD=Math.Min(p.DimD,3*Math.Max(p.DimA,1));q.DimE=p.DimE;q.Diameter=p.Diameter;return q;}case "HOOK1":return Sample("HOOK1",400,110,0);case "HOOK2":return Sample("HOOK2",110,400,110);case "STRAIGHT":return Sample("STRAIGHT",400,0,0);default:return p;}}
 static CutPiece Crank(){var p=Sample("CRANK",600,122,20);p.DimD=1400;return p;}
 static CutPiece CrankHook(){var p=Sample("CRANKHOOK",600,122,20);p.DimD=1400;p.DimE=300;return p;}
 static string Dim(double v){return v>0?v.ToString("0",Inv):"";}
 static CutPiece Sample(string code,double a,double b,double c){return new CutPiece{ShapeCode=code,DimA=a,DimB=b,DimC=c,Diameter=12};}
 /* one report per kind of member (owner, 20 November 2026: "sa report kung Beam lang beam lang, if column column lang, if slab
    slab lang"): the pieces, notes and commercial bars of that kind only */
 internal static readonly string[] Kinds={"Beam","Column","Slab","Footing","Wall footing"};
 internal static CutResult Only(CutResult r,string group,CutSettings s){var o=new CutResult();o.Pieces.AddRange(r.Pieces.Where(p=>p.Group==group));o.Deleted.AddRange(r.Deleted.Where(p=>p.Group==group));
  if(group=="Beam"){o.Geometry.AddRange(r.Geometry);o.Splices.AddRange(r.Splices);o.Spans.AddRange(r.Spans);o.Smf=r.Smf;}
  Func<string,bool> mine=n=>group=="Beam"?!Kinds.Where(k=>k!="Beam").Any(k=>n.StartsWith(k,StringComparison.OrdinalIgnoreCase)):n.StartsWith(group,StringComparison.OrdinalIgnoreCase);
  o.Notes.AddRange(r.Notes.Where(mine));o.Errors.AddRange(r.Errors.Where(e=>mine(e)&&!e.Contains("commercial")));BeamCutting.Purchase(o,s);return o;}
 public static CalculationDocument Build(CutResult r,CutSettings s,BbsInfo info,string group){return Build(Only(r,group,s),s,info);}
 public static CalculationDocument Build(CutResult r,CutSettings s,BbsInfo info){if(r==null)throw new Exception("Nothing to schedule yet: load a schedule and enter the beam lines.");
  var groups=r.Pieces.Select(p=>p.Group).Distinct().ToList();string members=string.Join(", ",new[]{"Beam","Column","Slab","Footing","Wall footing"}.Where(groups.Contains).Select(gn=>gn=="Wall footing"?"Wall Footings":gn+"s"));var rep=new RichReport("Bar Bending Schedule, Cutting List and Site Sheets - "+(members==""?"Beams":members),true);float width=RichReport.ContentWidth(true);var shown=r.Pieces.Where(p=>p.PerLine>0).ToList();
  rep.Paragraph("PART A - BAR BENDING SCHEDULE AND CUTTING LIST (engineering)",false,true).Heading("1  SCHEDULE INFORMATION").KeyValues(new[]{
   new[]{"BBS no. / revision",info.Number+" / rev. "+info.Revision},new[]{"Status",info.Status},new[]{"Date",DateTime.Now.ToString("yyyy-MM-dd",Inv)},new[]{r.Geometry.Count>0?"Beam schedule":"Source",info.Source},
   new[]{"Materials","fc' = "+s.Config.Input.Fc.ToString("0.#",Inv)+" MPa; Grade "+s.Config.GradeSmall+" (fy "+s.Config.FySmall.ToString("0",Inv)+" MPa) for 12 mm and smaller, Grade "+s.Config.GradeLarge+" (fy "+s.Config.FyLarge.ToString("0",Inv)+" MPa) for 16 mm and larger"},
   new[]{"Laps, development and hooks",s.Config.Name+" (Splice, Development & Hooks)"},new[]{"Clear cover",s.Cover.ToString("0",Inv)+" mm"},
   r.Geometry.Count==0?null:new[]{"Frame",s.SpecialMomentFrame?"Special moment frame - NSCP 2015 Section 418.6 / 418.8 (ACI 318-14 Ch. 18), ACI SP-66 detailing":"Ordinary frame / non-seismic"},
   r.Geometry.Count==0?null:new[]{"Curtailment",info.Curtailment},new[]{"Cut lengths",s.CutRounding>0?"rounded up to multiples of "+s.CutRounding.ToString("0.##",Inv)+" mm":"exact (1 mm)"},new[]{"Commercial lengths",CommercialBars.FormatLengths(s.Stocks)+" m; longest bar used "+s.MaxBar.ToString("0.##",Inv)+" m"}}.Where(x=>x!=null).ToArray());
  int skip=r.Geometry.Count>0?0:1;/* a column, slab or footing report has no beam lines or beam details section */
  if(skip==0)rep.Table(new[]{"Beam line","Span","Mark","b x h (mm)","Ln (m)","Left support (mm)","Right support (mm)","Slab (mm)","Identical lines","In estimate"},r.Geometry.SelectMany(g=>Enumerable.Range(0,g.Ln.Length).Select(j=>{var e=r.Spans.FirstOrDefault(x=>x.Line==g.Line&&x.Span==j+1);return new[]{g.Line,(j+1).ToString(Inv),g.Marks[j],(g.Width[j]*1000).ToString("0",Inv)+" x "+(g.Depth[j]*1000).ToString("0",Inv),g.Ln[j].ToString("0.000",Inv),(g.SupportWidth[j]*1000).ToString("0",Inv),(g.SupportWidth[j+1]*1000).ToString("0",Inv),(g.Slab[j]*1000).ToString("0",Inv),e==null?"1":e.Quantity.ToString(Inv),e==null||e.Include?"Yes":"No"};})),new float[]{10,6,10,12,9,13,13,9,10,8});
  rep.Heading("2  SHAPE KEY - BAR SHAPE REFERENCE").Figure(170,(g,rect)=>{var samples=new[]{new KeyValuePair<string,CutPiece>("S0",Sample("STRAIGHT",900,0,0)),new KeyValuePair<string,CutPiece>("L1",Sample("HOOK1",700,300,0)),new KeyValuePair<string,CutPiece>("U2",Sample("HOOK2",300,700,300)),new KeyValuePair<string,CutPiece>("H5",Sample("HOOP",220,420,90)),new KeyValuePair<string,CutPiece>("X3",Sample("CROSSTIE",420,90,90)),new KeyValuePair<string,CutPiece>("K4",Crank()),new KeyValuePair<string,CutPiece>("K5",CrankHook())};var usedCodes=new HashSet<string>(r.Pieces.Select(x=>Code(x.ShapeCode)));if(usedCodes.Count>0)samples=samples.Where(k=>usedCodes.Contains(k.Key)).ToArray();
    float w=rect.Width/Math.Max(samples.Length,5);using(var f=new Font("Segoe UI",7.5f,FontStyle.Regular,GraphicsUnit.Point))using(var b=new Font("Segoe UI",7.5f,FontStyle.Bold,GraphicsUnit.Point))using(var ink=new SolidBrush(PowTheme.Ink))for(int k=0;k<samples.Length;k++){float x=rect.Left+k*w;g.DrawString(samples[k].Key,b,ink,new RectangleF(x+4,rect.Top+4,w-8,24));BarShapes.Draw(g,new RectangleF(x+8,rect.Top+34,w-16,rect.Height-40),samples[k].Value,true,Color.FromArgb(25,90,160),b,false,2f,true);}},
   "A to E = outside dimensions (mm); R = inside bend radius; seismic hooks 135°, extension >= max(6db, 75).");
  if(skip==0)rep.Heading("3  BEAM DETAILS - ELEVATION AND SECTIONS");
  foreach(var geo0 in r.Geometry){var geo=geo0;var strips=BeamDetailPaper.Strips(geo);foreach(var st0 in strips){var st=st0;rep.Figure(BeamDetailPaper.ElevationHeight(r,geo),(g,rect)=>BeamDetailPaper.DrawElevation(g,rect,r,geo,st[0],st[1]),"Elevation of beam line "+geo.Line+(strips.Count>1?", spans "+(st[0]+1)+" to "+(st[1]+1)+" (strip "+(strips.IndexOf(st)+1)+" of "+strips.Count+", strips meet at the match lines)":"")+": bars, laps, hoop zones, the section cuts and the dimension chains (2h zones and allowed splice zones); bar codes in the bar details below.");rep.Figure(BeamDetailPaper.BarDetailsHeight(r,geo,st[0],st[1]),(g,rect)=>BeamDetailPaper.DrawBarDetails(g,rect,r,geo,st[0],st[1]),"Bar details of beam line "+geo.Line+": main top straight bars, cut top bars, main bottom straight bars and cut bottom bars with their codes and cut lengths, at the scale of the elevation.");}
   int rows=BeamDetailPaper.SectionRows(r,geo,width);for(int first=0;first<rows;first+=2){int f=first,n=Math.Min(2,rows-first);rep.Figure(BeamDetailPaper.SectionsHeight(n),(g,rect)=>BeamDetailPaper.DrawSections(g,rect,r,geo,f,n),"Sections of beam line "+geo.Line+(rows>2?" ("+(f/2+1)+")":"")+" at the left face (A), midspan (B) and right face (C) of the spans, to the scale shown; identical sections are drawn once (TYP.) with the cuts they stand for.");}}
  AddElementSchedules(rep,r,s,(4-skip).ToString(Inv));
  rep.Paragraph("Lengths in mm. * added on the cutting list, † edited on the cutting list. Cut lengths include the bend allowances; check the bent shape on site against A, B, C.",true);
  var weights=r.Pieces.GroupBy(x=>new{x.Grade,x.Diameter}).OrderBy(x=>x.Key.Grade).ThenBy(x=>x.Key.Diameter).Select(x=>new[]{"Grade "+x.Key.Grade,"Ø"+x.Key.Diameter+" mm",EstimatorEngine.UnitMass(x.Key.Diameter).ToString("0.000",Inv),x.Sum(p=>p.Pieces*p.Length).ToString("0.00",Inv),x.Sum(p=>p.Kg).ToString("0.00",Inv)}).ToList();weights.Add(new[]{"TOTAL","","","",r.Pieces.Sum(p=>p.Kg).ToString("0.00",Inv)});
  rep.Heading((5-skip)+"  WEIGHT SUMMARY").Table(new[]{"Grade","Bar size","Unit mass (kg/m)","Total length (m)","Weight (kg)"},weights,new float[]{18,18,20,22,22},row=>row[0]=="TOTAL"?(Color?)Color.FromArgb(232,236,240):null);
  if(groups.Count>1){var byGroup=new[]{"Beam","Column","Slab","Footing","Wall footing"}.Where(groups.Contains).Select(gn=>{var ps=r.Pieces.Where(p=>p.Group==gn).ToList();return new[]{gn,ps.Count.ToString(Inv),ps.Sum(p=>p.Pieces).ToString(Inv),ps.Sum(p=>p.Pieces*p.Length).ToString("0.00",Inv),ps.Sum(p=>p.Kg).ToString("0.00",Inv)};}).ToList();rep.Table(new[]{"Member type","Bar marks","Pieces","Total length (m)","Weight (kg)"},byGroup,new float[]{24,16,16,22,22});}
  rep.Heading((6-skip)+"  CUTTING LIST - CUTTING PATTERN PER COMMERCIAL BAR").Table(new[]{"Pattern","Grade / size","Stock (m)","No. of bars","Cuts from each bar","For bar marks (total pieces)","Offcut (m)"},
   r.Patterns.Select(p=>new[]{p.Id,"G"+p.Grade+" Ø"+p.Diameter,p.Stock.ToString("0.0#",Inv),p.Bars.ToString(Inv),CuttingPatterns.Describe(p),CuttingPatterns.MarksOf(p),p.Offcut.ToString("0.000",Inv)+(p.Offcut>=CuttingPatterns.ReusableOffcut?" (keep)":"")}),new float[]{8,9,7,7,22,36,11});
  var order=CuttingPatterns.Summary(r.Patterns);
  rep.Table(new[]{"Order","Bars to buy","Bought (m)","Cut (m)","Offcut %","Weight bought (kg)"},order.Select(o=>new[]{"G"+o.Grade+" Ø"+o.Diameter,string.Join(", ",o.BarsByStock.OrderByDescending(k=>k.Key).Select(k=>k.Value+" x "+k.Key.ToString("0.0#",Inv)+" m")),o.Bought.ToString("0.00",Inv),o.Used.ToString("0.00",Inv),o.WastePercent.ToString("0.0",Inv),o.Kg.ToString("0.00",Inv)}),new float[]{12,34,13,13,11,17});
  rep.Paragraph("Patterns by best-fit decreasing: longest pieces first, each into the bar it fills best; each bar bought at the shortest commercial length that holds its cuts. Offcuts of "+CuttingPatterns.ReusableOffcut.ToString("0.0",Inv)+" m or more are marked (keep) for reuse. No saw kerf (sheared).",true);
  int section=7-skip;
  if(s.SpecialMomentFrame&&r.Smf.Count>0){rep.Heading(section+"  SPECIAL MOMENT FRAME DETAILING CHECK (NSCP 2015 418.6 / 418.8)").Table(new[]{"Line","Span","Check","Clause","Required","Provided","Result"},r.Smf.Select(c=>new[]{c.Line,c.Span>0?c.Span.ToString(Inv):"-",c.Item+(c.Note!=""?" - "+c.Note:""),c.Clause,c.Required,c.Provided,c.Ok?"OK":"NOT OK"}),new float[]{6,6,30,13,17,19,9},row=>row[6]=="OK"?null:(Color?)Color.FromArgb(252,232,232));
   rep.Paragraph("Moment strengths are compared through the steel areas of the same section. Not checked here (structural design): beam width against the column width (418.6.2.1(c)), joint shear (418.8.4), strong column - weak beam (418.7.3) and the shear design of the hoops (418.6.5).",true);section++;}
  if(r.Splices.Count>0){rep.Heading(section+"  SPLICE ZONE CHECK").Table(new[]{"Line","Bar","Ø","Span","Lap from - to (m)","Allowed zone (m)","Lap (m)","Result","Note"},r.Splices.Select(c=>new[]{c.Line,c.Shown,c.Diameter.ToString(Inv),c.Span.ToString(Inv),c.From.ToString("0.000",Inv)+" - "+c.To.ToString("0.000",Inv),c.ZoneFrom.ToString("0.000",Inv)+" - "+c.ZoneTo.ToString("0.000",Inv),c.Lap.ToString("0.000",Inv),c.Status,c.Note}),new float[]{7,8,4,5,14,14,7,7,34},row=>row[7]=="OK"?null:(Color?)Color.FromArgb(252,232,232));section++;}
  {var dias=r.Spans.SelectMany(e=>e.KgByDiameter.Keys).Distinct().OrderBy(d=>d).ToList();var rows=r.Spans.Select(e=>new[]{e.Line,e.Span.ToString(Inv),e.Mark,e.Include?"Yes":"No",e.Ln.ToString("0.000",Inv),e.Quantity.ToString(Inv)}.Concat(dias.Select(d=>{double v;return (e.KgByDiameter.TryGetValue(d,out v)?v:0).ToString("0.00",Inv);})).Concat(new[]{e.Kg.ToString("0.00",Inv),e.Ties.ToString(Inv),e.Concrete.ToString("0.000",Inv),e.Formwork.ToString("0.00",Inv)}).ToArray()).ToList();
   var inc=r.Spans.Where(e=>e.Include).ToList();rows.Add(new[]{"INCLUDED SPANS","","","","",""}.Concat(dias.Select(d=>inc.Sum(e=>{double v;return e.KgByDiameter.TryGetValue(d,out v)?v:0;}).ToString("0.00",Inv))).Concat(new[]{r.IncludedKg.ToString("0.00",Inv),inc.Sum(e=>e.Ties).ToString(Inv),r.IncludedConcrete.ToString("0.000",Inv),r.IncludedFormwork.ToString("0.00",Inv)}).ToArray());
   rep.Heading(section+"  ESTIMATE PER SPAN").Table(new[]{"Line","Span","Mark","In estimate","Ln (m)","Identical lines"}.Concat(dias.Select(d=>"Ø"+d+" (kg)")).Concat(new[]{"Rebar (kg)","Hoop sets","Concrete (m³)","Forms (m²)"}).ToArray(),rows,new float[]{8,5,8,7,7,7}.Concat(dias.Select(d=>8f)).Concat(new float[]{9,8,9,9}).ToArray(),row=>row[0]=="INCLUDED SPANS"?(Color?)Color.FromArgb(232,236,240):row[3]=="No"?(Color?)Color.FromArgb(245,245,245):null);
   rep.Paragraph("Steel of bars crossing several spans is shared by length; concrete and forms use the beam below the slab over the clear span. Unticked spans are left out: only the dowels (abang) of the spans beside them are listed.",true);section++;}
  int open=r.Errors.Count+r.Splices.Count(c=>!c.Ok)+r.Smf.Count(c=>!c.Ok);
  rep.Heading(section+"  REVIEW AND NOTES");rep.Paragraph(open==0?"No open review items.":open+" OPEN REVIEW ITEM(S) - resolve before issue for construction.",false,true);foreach(var e in r.Errors)rep.Paragraph("• "+e);
  if(r.Pieces.Any(x=>x.Manual||x.Edited)||r.Deleted.Count>0)rep.Paragraph("• Edited on the cutting list: "+r.Pieces.Count(x=>x.Edited&&!x.Manual)+" bar(s) changed, "+r.Pieces.Count(x=>x.Manual)+" added, "+r.Deleted.Count+" removed"+(r.Deleted.Count>0?" ("+string.Join(", ",r.Deleted.Select(x=>x.BarMark))+")":"")+".");
  foreach(var n in r.Notes)rep.Paragraph("• "+n);
  rep.Paragraph("• Shape codes S0, L1, U2, H5, X3 are the codes of this schedule (sketch and A / B / C govern); they are not BS 8666 or CRSI shape numbers.",true);
  rep.Signatures(Role("Prepared by",info.Prepared),Role("Checked by",info.Checked),Role("Approved by",info.Approved));
  rep.Paragraph("Valid for construction only when signed by the responsible engineer. Generated by DTCE Tool Kit v"+Engine.Version+"; the program does not approve this schedule.",true);
  /* part B: the crew sheets (owner: "Icomvine mo na silang tatlo") */
  rep.PageBreak().Paragraph("PART B - SITE SHEETS FOR THE CREW",false,true);SiteSheets.AddCrew(rep,r,s,info,false);
  return rep.Build();}
 static string Role(string role,string name){return string.IsNullOrWhiteSpace(name)?role:role+": "+name.Trim();}
}
